import{c as i,Q as s,j as t,m as a}from"./chunks/framework.CyZn50Me.js";const u=JSON.parse('{"title":"Security Review Playbook","description":"","frontmatter":{},"headers":[],"relativePath":"ops/security-review-playbook.md","filePath":"ops/security-review-playbook.md"}'),n={name:"ops/security-review-playbook.md"};function o(l,e,r,c,p,d){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="security-review-playbook" tabindex="-1">Security Review Playbook <a class="header-anchor" href="#security-review-playbook" aria-label="Permalink to &quot;Security Review Playbook&quot;">​</a></h1><p>Reusable runbook for the periodic security review of Orrery. First produced for GH #96 (v0.7.0 cycle, 2026-05-29). Run end-of-cycle, before major releases, or any time the surface area materially changes (new server route, new external data source, new third-party script, new deploy target).</p><h2 id="threat-model-recompute-each-review" tabindex="-1">Threat model (recompute each review) <a class="header-anchor" href="#threat-model-recompute-each-review" aria-label="Permalink to &quot;Threat model (recompute each review)&quot;">​</a></h2><p>Orrery is a fully <strong>static, public-facing educational web app</strong> with <strong>no user accounts, no payments, no PII collection</strong>. The audit must verify these are still true before applying this playbook — if any of them change, expand the threat model accordingly.</p><p>Default-applicable threat surfaces:</p><ul><li><strong>Supply chain</strong> — npm deps + GH Actions third-party actions</li><li><strong>Build-time data ingress</strong> — agency/CDN URLs fetched during build</li><li><strong>Client XSS</strong> — <code>{@html}</code>, dynamic SVG, image src from JSON</li><li><strong>Telemetry leak</strong> — Sentry / RUM accidentally capturing PII</li><li><strong>Deploy pipeline</strong> — secrets handling, SSH/Tailnet config, container env</li><li><strong>CSP / headers</strong> — defense-in-depth posture at nginx</li><li><strong>Pre-commit / pre-push gates</strong> — secret scanners, data validation</li></ul><h2 id="how-to-run-the-review" tabindex="-1">How to run the review <a class="header-anchor" href="#how-to-run-the-review" aria-label="Permalink to &quot;How to run the review&quot;">​</a></h2><h3 id="step-0-—-establish-trust-baseline" tabindex="-1">Step 0 — Establish trust baseline <a class="header-anchor" href="#step-0-—-establish-trust-baseline" aria-label="Permalink to &quot;Step 0 — Establish trust baseline&quot;">​</a></h3><ol><li>Confirm <code>main</code> is clean: <code>git status</code>, <code>git log --oneline -10</code>.</li><li>Confirm milestone scope (e.g. v0.7.0 milestone open issues).</li><li>Re-read the threat-model assumptions above. Any of them now false? If yes, expand scope before continuing.</li></ol><h3 id="step-1-—-empirical-scan-parallel" tabindex="-1">Step 1 — Empirical scan (parallel) <a class="header-anchor" href="#step-1-—-empirical-scan-parallel" aria-label="Permalink to &quot;Step 1 — Empirical scan (parallel)&quot;">​</a></h3><p>Run these in parallel — they are independent and each takes minutes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A. Dependency vulnerabilities — what&#39;s currently shipping</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/orrery-npm-audit.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{summary: .metadata.vulnerabilities, advisories: [.vulnerabilities | to_entries[] | {pkg: .key, severity: .value.severity, via: (.value.via | if type==&quot;array&quot; then map(if type==&quot;object&quot; then .title else . end) else [.] end), range: .value.range, fixAvailable: .value.fixAvailable}]}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/orrery-npm-audit.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># B. Committed secrets / hardcoded credentials</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.env*&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -not</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*/node_modules/*&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -not</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*/.git/*&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rEn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;sk_live|pk_live|AKIA|ghp_[A-Za-z0-9]{36}|glpat-|xoxb-|Bearer [A-Za-z0-9]{20,}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.ts&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.js&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.svelte&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.yaml&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.yml&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.toml&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --exclude-dir=node_modules</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exclude-dir=.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># C. Unpinned third-party GH Actions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;uses: [^@]+@(main|master|v[0-9]+(\\.[0-9]+)?|[a-z]+)$&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .github/workflows/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.yml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># D. pull_request_target footguns</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;pull_request_target&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .github/workflows/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.yml</span></span></code></pre></div><p>Then dispatch an Explore agent for the structured 12-area sweep below. The agent must cite <code>file:line</code> for every claim — no &quot;appears to&quot; / &quot;looks like&quot;.</p><h3 id="step-2-—-the-12-areas-explore-agent-prompt-template" tabindex="-1">Step 2 — The 12 areas (Explore agent prompt template) <a class="header-anchor" href="#step-2-—-the-12-areas-explore-agent-prompt-template" aria-label="Permalink to &quot;Step 2 — The 12 areas (Explore agent prompt template)&quot;">​</a></h3><p>For each area: gather evidence, then grade <code>✓ safe | ⚠ partial | ✗ broken | N/A</code>.</p><ol><li><strong>Server-side runtime surface</strong> — which adapter (<code>svelte.config.js</code>)? Any <code>+server.ts</code>, <code>+page.server.ts</code>, <code>+layout.server.ts</code>, <code>hooks.server.ts</code>? Any form <code>actions = {}</code> handlers?</li><li><strong>XSS surface</strong> — every <code>{@html}</code> in <code>src/**/*.svelte</code>: where does the HTML come from (static i18n / build-time JSON / external feed / user input)? Any <code>innerHTML =</code>, <code>document.write</code>, dynamic SVG construction, externally-sourced <code>&lt;img src&gt;</code>?</li><li><strong>Dependencies</strong> — <code>package.json</code> + lock committed? Any postinstall scripts in deps (<code>npm ls --long | grep postinstall</code> or scan <code>node_modules/*/package.json</code>)? Cross-check installed versions against <code>npm audit</code> advisories from Step 1.</li><li><strong>CSP and security headers</strong> — <code>app.html</code> meta CSP? <code>hooks.server.ts</code> setting headers? <code>svelte.config.js</code> <code>csp:</code> block? Reverse-proxy config (nginx in <code>docs/ops/</code>)? Sub-resource Integrity on third-party <code>&lt;script&gt;</code> / <code>&lt;link&gt;</code>?</li><li><strong>Secrets and env handling</strong> — every <code>process.env.X</code>, <code>$env/static/private</code>, <code>$env/dynamic/private</code>, <code>$env/static/public</code>, <code>$env/dynamic/public</code>. Private vars must not leak into the browser bundle. <code>PUBLIC_*</code> vars are baked at build time.</li><li><strong>GitHub Actions</strong> — for each workflow: triggers (esp. <code>pull_request_target</code>), <code>permissions:</code> block scope, interpolation of <code>github.event.*</code> fields (issue title, PR body, branch name) inside <code>run:</code> scripts via the GHA template syntax (workflow injection risk), third-party actions pinned to SHA vs tag, secrets accessed in jobs that also check out PR-controlled code.</li><li><strong>Service worker</strong> — registered scope, what&#39;s precached (<code>globPatterns</code>, <code>globIgnores</code>), <code>maximumFileSizeToCacheInBytes</code>, runtime caching strategy per route, <code>registerType</code> (<code>autoUpdate</code> vs <code>prompt</code>), update-check cadence. Does it intercept POSTs?</li><li><strong>Deploy pipeline</strong> — Hetzner deploy workflow + script. SSH key written at mode 600? Host key in <code>known_hosts</code>? <code>.env</code> staged atomically (mktemp → scp → mv)? Container env passed only via env file (no <code>--env</code> on cmdline that ends up in <code>ps</code>)? Tailscale ACL tag scope? Rollback story?</li><li><strong>Telemetry / privacy</strong> — Sentry: <code>beforeSend</code> scrubs URLs/headers/cookies? <code>sendDefaultPii: false</code>? Replay disabled? Analytics: production-only host check? Cookies: enumerate every <code>Set-Cookie</code> / <code>document.cookie</code>. localStorage / sessionStorage usage (project rule: forbidden — verify).</li><li><strong>Data integrity</strong> — image / data fetch scripts: live fetch at build time vs pinned. Image-provenance manifest signed or checksum-only? <code>validate-data</code> gate covering all data classes? <code>check-no-secrets</code> gate covering all credential patterns?</li><li><strong>Authentication / authorization</strong> — confirm no <code>/login</code>, no <code>/admin</code>, no <code>auth</code>, no <code>password</code>, no <code>session</code>, no <code>jwt</code> matches in <code>src/</code>. Confirm no user accounts in any data file.</li><li><strong>Existing security testing</strong> — Dependabot config? CodeQL? Snyk? axe-core gate? Per-PR <code>npm audit</code> step?</li></ol><h3 id="step-3-—-reconcile-agent-output-with-npm-audit" tabindex="-1">Step 3 — Reconcile agent output with <code>npm audit</code> <a class="header-anchor" href="#step-3-—-reconcile-agent-output-with-npm-audit" aria-label="Permalink to &quot;Step 3 — Reconcile agent output with \`npm audit\`&quot;">​</a></h3><p>The agent reads <code>package.json</code> versions, not the actually-resolved tree. <strong>Always reconcile</strong>:</p><ul><li>A pinned-old SvelteKit / Vite / esbuild can still have outstanding advisories even when the project is static.</li><li>A &quot;static site&quot; doesn&#39;t immunize against client-side reactive patterns (e.g. <code>searchParams</code> XSS advisories apply to client-side subscribers, not only to server routes).</li><li>Transitive deps (e.g. <code>tar</code> under <code>gdal-async</code>) won&#39;t show in top-level <code>package.json</code>.</li></ul><p>If <code>npm audit</code> reports anything <code>high</code> or <code>critical</code>, treat as a finding regardless of the agent&#39;s verdict.</p><h3 id="step-4-—-rank-findings" tabindex="-1">Step 4 — Rank findings <a class="header-anchor" href="#step-4-—-rank-findings" aria-label="Permalink to &quot;Step 4 — Rank findings&quot;">​</a></h3><p>Per-finding scoring: <code>priority = likelihood × impact_in_orrery_context</code>. Bucket into:</p><ul><li><strong>Critical</strong> — exploitable now, ship before next deploy</li><li><strong>High</strong> — meaningful vuln, ship within the current milestone</li><li><strong>Medium</strong> — defense-in-depth or moderate-severity, schedule for next cycle</li><li><strong>Low</strong> — hardening, opportunistic</li><li><strong>Defer</strong> — known, accepted, documented</li></ul><p>Be honest: a <code>high</code>-severity npm advisory that requires a server runtime Orrery doesn&#39;t have is NOT <code>high</code> in our context — re-classify with rationale.</p><h3 id="step-5-—-action-plan" tabindex="-1">Step 5 — Action plan <a class="header-anchor" href="#step-5-—-action-plan" aria-label="Permalink to &quot;Step 5 — Action plan&quot;">​</a></h3><p>For each Critical/High item:</p><ul><li>File path or workflow to edit</li><li>Specific change (&quot;bump @sveltejs/kit ^2.10.1 → ^2.61.1, run <code>npm run preflight</code>, run full e2e on both projects&quot;)</li><li>Verification step</li><li>Test gate that proves it shipped</li></ul><p>For Medium/Low: a one-line TODO under <code>docs/wip/security-followups.md</code> (create if missing).</p><h3 id="step-6-—-document-outcome" tabindex="-1">Step 6 — Document outcome <a class="header-anchor" href="#step-6-—-document-outcome" aria-label="Permalink to &quot;Step 6 — Document outcome&quot;">​</a></h3><p>Comment on the security-review GH issue with:</p><ul><li>Date of review</li><li>Scope (which commit SHA reviewed)</li><li>Top findings (Critical/High)</li><li>Resolution path (PR refs / commit refs)</li></ul><p>Do not close the umbrella issue automatically; security review is a recurring milestone activity.</p><h2 id="per-review-checklist-copy-paste" tabindex="-1">Per-review checklist (copy-paste) <a class="header-anchor" href="#per-review-checklist-copy-paste" aria-label="Permalink to &quot;Per-review checklist (copy-paste)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- [ ] Threat-model assumptions still true (no auth, no PII, no payments)</span></span>
<span class="line"><span>- [ ] npm audit run + reconciled with package.json versions</span></span>
<span class="line"><span>- [ ] All 12 areas swept with file:line evidence</span></span>
<span class="line"><span>- [ ] Workflow injection (github.event.*) audited</span></span>
<span class="line"><span>- [ ] Pinned-action audit (sha vs tag) audited</span></span>
<span class="line"><span>- [ ] Secrets-handling sample sanity-check on the latest deploy workflow run</span></span>
<span class="line"><span>- [ ] Top-risk list ranked Critical → Defer</span></span>
<span class="line"><span>- [ ] Action plan filed (PR or follow-up issues)</span></span>
<span class="line"><span>- [ ] GH issue commented with review record</span></span></code></pre></div><h2 id="limits-of-this-playbook" tabindex="-1">Limits of this playbook <a class="header-anchor" href="#limits-of-this-playbook" aria-label="Permalink to &quot;Limits of this playbook&quot;">​</a></h2><ul><li><strong>Not a pen-test.</strong> No live probing of deployed surface (Hetzner / GH Pages). Code-and-config only.</li><li><strong>No legal/compliance review.</strong> GDPR / CCPA text and policy live elsewhere.</li><li><strong>No human-process audit.</strong> Insider risk, credential rotation cadence, off-boarding — separate review.</li><li><strong>Snapshot in time.</strong> Catches latent issues in the reviewed SHA; doesn&#39;t catch what lands after.</li></ul><h2 id="trigger-cadence" tabindex="-1">Trigger cadence <a class="header-anchor" href="#trigger-cadence" aria-label="Permalink to &quot;Trigger cadence&quot;">​</a></h2><ul><li>End of every minor version cycle (v0.X.0 → v0.X+1.0)</li><li>Before cutting a major release</li><li>After landing any of: new server adapter, new third-party script, new deploy target, new external data source, new secret class</li></ul><hr><p><em>docs/ops/security-review-playbook.md — born from GH #96 review on 2026-05-29. Update each cycle with what worked / what missed.</em></p>`,40)])])}const g=i(n,[["render",o]]);export{u as __pageData,g as default};
